// Given template Stack for ex15 .. ex17 (like the one in the 27 October lab).
// Do not edit this file: use only its public operations (push, pop, getTop, isEmpty).
#ifndef TSTACK_H
#define TSTACK_H

template <class T>
class Stack {
public:
    Stack() : topPtr(nullptr) {}
    Stack(const Stack& other) : topPtr(nullptr) {
        StackNode** tail = &topPtr;
        for (StackNode* cur = other.topPtr; cur != nullptr; cur = cur->next) {
            *tail = new StackNode{cur->item, nullptr};
            tail = &(*tail)->next;
        }
    }
    ~Stack() { while (pop()) {} }
    Stack& operator=(const Stack&) = delete;

    bool isEmpty() const { return topPtr == nullptr; }
    bool push(const T& newItem) { topPtr = new StackNode{newItem, topPtr}; return true; }
    bool pop() {
        if (isEmpty()) return false;
        StackNode* temp = topPtr;
        topPtr = topPtr->next;
        delete temp;
        return true;
    }
    bool pop(T& stackTop) {
        if (isEmpty()) return false;
        stackTop = topPtr->item;
        return pop();
    }
    bool getTop(T& stackTop) const {
        if (isEmpty()) return false;
        stackTop = topPtr->item;
        return true;
    }

    void insertSorted(const T& x);                     // ex15
    bool isPalindrome();                               // ex17

private:
    struct StackNode {
        T item;
        StackNode* next;
    };
    StackNode* topPtr;
};

#endif
